mapper.select:
select gs.id, gs.stock_date, gs.mix_area, gs.glue, gs.stock_num, s.SAFE_STOCK, gs.remark, gs.del_flag, gs.create_by, gs.create_time, gs.update_by, gs.update_time, gs.bar_code, gs.valid_time, gs.stock_weight from t_glue_stock gs left join t_glue_safe_stock s on gs.mix_area=s.mix_area and gs.glue=s.glue and s.del_flag = '0' where gs.del_flag = '0' and gs.stock_date = #{stockDate} and gs.mix_area = #{mixArea} and INSTR(gs.glue, #{glue}) > 0
order by stock_date desc,valid_time asc
order by ${orderStr}

WITH temp_table AS (

    SELECT #{rowNumber} row_numbers, #{data.stockDate,jdbcType=TIMESTAMP}
    STOCK_DATE,#{data.barCode,jdbcType=VARCHAR}
    BAR_CODE


)
select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy,
now() createTime
from t_glue_stock m
inner join temp_table t on m.STOCK_DATE = t.STOCK_DATE and m.BAR_CODE = t.BAR_CODE and
m.del_flag ='0'

mapper.insert:
insert into t_glue_stock (id,stock_date,mix_area,glue,stock_num,remark,del_flag,create_by,create_time,update_by,update_time,bar_code,valid_time,stock_weight ) select NULL id, x.* from (
select #{tGlueStock.stockDate,jdbcType=TIMESTAMP} stock_date, #{tGlueStock.mixArea,jdbcType=VARCHAR} mix_area, #{tGlueStock.glue,jdbcType=VARCHAR} glue, #{tGlueStock.stockNum,jdbcType=DOUBLE} stock_num, #{tGlueStock.remark,jdbcType=VARCHAR} remark, #{tGlueStock.delFlag,jdbcType=VARCHAR} del_flag, #{tGlueStock.createBy,jdbcType=VARCHAR} create_by, #{tGlueStock.createTime,jdbcType=TIMESTAMP} create_time, #{tGlueStock.updateBy,jdbcType=VARCHAR} update_by, #{tGlueStock.updateTime,jdbcType=TIMESTAMP} update_time, #{tGlueStock.barCode,jdbcType=VARCHAR} BAR_CODE,#{tGlueStock.validTime,jdbcType=TIMESTAMP} VALID_TIME, #{tGlueStock.stockWeight,jdbcType=DOUBLE} stock_weight
) x
